import pandas as pd
import matplotlib.pyplot as plt
import os

def generate_exploration_charts():
    # Load the exploration data report generated by collecte.py
    report_path = "rapports/exploration_donnees_brutes.csv"
    if not os.path.exists(report_path):
        print("[-] Run collecte.py first!")
        return

    df = pd.read_csv(report_path)
    os.makedirs("rapports", exist_ok=True)

    # Graph 1: Word Count per Article
    plt.figure(figsize=(8, 5))
    plt.bar(df.index, df["word_count"], color="skyblue", edgecolor="black")
    plt.xlabel("Index de l'article")
    plt.ylabel("Nombre de mots")
    plt.title("Étape 2 - Graphique 1 : Distribution de la longueur des résumés")
    plt.savefig("rapports/graph_longueur_mots.png")
    plt.close()
    print("[+] Graph 1 saved to rapports/graph_longueur_mots.png")

    # Graph 2: Character Count Distribution
    plt.figure(figsize=(8, 5))
    plt.hist(df["character_count"], bins=5, color="orange", edgecolor="black")
    plt.xlabel("Nombre de caractères")
    plt.ylabel("Fréquence")
    plt.title("Étape 2 - Graphique 2 : Histogramme des caractères par résumé")
    plt.savefig("rapports/graph_histogramme_caracteres.png")
    plt.close()
    print("[+] Graph 2 saved to rapports/graph_histogramme_caracteres.png")

if __name__ == "__main__":
    generate_exploration_charts()